arguments.content:
//! JQ-style query language for filtering and transforming JSON values.
//!
//! Re-exported from `memory-kernel`, which owns this generic primitive so it
//! can be reused by non-server binaries (e.g. peek-cli).

pub use memory_kernel::query::*;

arguments.oldString:
uuid = { version = "1", features = ["v4"] }
tower = { version = "0.4", features = ["util"] }

# jq query language
jaq-core = "1"
jaq-std = "1"
jaq-interpret = "1"
jaq-syn = "1"

# Domain types and log parser from context-api
context-api = { git = "https://github.com/mankinskin/context-stack", branch = "main" }

arguments.newString:
uuid = { version = "1", features = ["v4"] }
tower = { version = "0.4", features = ["util"] }

